[InitializeOnLoad]public static class WorkingMarinaFinish{const string D="Assets/Scenes/Oasis/YachtPortAtlas";static WorkingMarinaFinish(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("WorkingMarinaFinish.request"))return;File.Delete("WorkingMarinaFinish.request");Run();}static void Run(){try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var yard=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads").GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Yatch_Port");var root=yard.transform.Find("Reference Working Marina Features");if(!root)root=yard.transform.Cast<Transform>().Single(t=>t.GetComponentsInChildren<MeshFilter>().Any(f=>f.name=="Harbour operations office"));var pad=root.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Left helicopter landing pad").sharedMesh;pad.uv=new[]{new Vector2(0,0),new Vector2(1,0),new Vector2(0,1),new Vector2(1,1)};EditorUtility.SetDirty(pad);var bound=yard.sharedMesh.bounds;float y=yard.sharedMesh.vertices.Max(v=>v.y);var type=typeof(ReferenceWorkingMarina).GetNestedType("Geo",BindingFlags.NonPublic);var geo=Activator.CreateInstance(type);var pole=type.GetMethod("Pole");var box=type.GetMethod("Box");var mat=yard.GetComponent<MeshRenderer>().sharedMaterial;float z=-bound.size.z/2;for(float x=-bound.size.x/2+10;x<bound.size.x/2-10;x+=14)pole.Invoke(geo,new object[]{new Vector3(x,y-1.8f,z-.2f),new Vector3(x,y-.3f,z-.2f),.21f,-1,new Color(.035f,.04f,.038f),8});for(int i=0;i<4;i++)box.Invoke(geo,new object[]{new Vector3(0,y-.2f-i*.32f,z-.7f-i*.5f),new Vector3(5,.32f,1),-1,new Color(.72f,.72f,.67f),0f});var mesh=(Mesh)type.GetMethod("Save").Invoke(geo,new object[]{"Quay Fenders and Boarding Steps"});var g=new GameObject("Rubber quay fenders and boarding steps");g.transform.SetParent(root,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=mat;var source=PrefabUtility.LoadPrefabContents(D+"/Reference Working Marina Features.prefab");var clone=UnityEngine.Object.Instantiate(g,source.transform);clone.name=g.name;PrefabUtility.SaveAsPrefabAsset(source,D+"/Reference Working Marina Features.prefab");PrefabUtility.UnloadPrefabContents(source);UnityEngine.Object.DestroyImmediate(g);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var center=yard.transform.TransformPoint(new Vector3(0,y,0));var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,center+yard.transform.TransformDirection(new Vector3(0,95,-118)),center,"Reference-Working-Marina-Overview"});capture.Invoke(null,new object[]{scene,center+yard.transform.TransformDirection(new Vector3(15,25,-42)),center+yard.transform.TransformDirection(new Vector3(0,3,20)),"Reference-Marina-Office-Closeup"});int renderers=0,other=0,triangles=0;foreach(var r in root.GetComponentsInChildren<MeshRenderer>()){renderers++;other+=r.sharedMaterials.Count(m=>m!=mat);triangles+=r.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3;}File.WriteAllText("FinalEnvironmentRoadReview/WorkingMarinaValidation.txt","near renderers="+renderers+" triangles="+triangles+" non-shared material references="+other+"; ground collision="+(yard.GetComponent<MeshCollider>().sharedMesh==yard.sharedMesh)+"; shader errors="+ShaderUtil.GetShaderMessages(mat.shader).Count(m=>m.severity.ToString()=="Error")+"; helipad H corrected; quay fenders and boarding steps saved in feature prefab.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/WorkingMarinaValidation.txt","FAILED "+e);Debug.LogException(e);}}}
